//open.canada.ca/data/dataset/0bb1fb56-74d0-47f4-b4b3-2b574229416d/resource/bba998e0-c882-4120-91b5-c6af24ac228d/download/directors_2014_updated.csv","title":"CRA T3010 directors/trustees and like officials, UNIVERSITY OF ONTARIO INSTITUTE OF TECHNOLOGY (BN 859248049RR0001), fiscal period ending 2014-03-31","publisher":"Canada Revenue Agency (Government of Canada open data)","date":"2014-03-31","kind":"public_record","registry":"CRA List of Charities / T3010 returns (2014 dataset, Directors)","record_id":"859248049RR0001","note":"T3010 directors/trustees data lists Marj Rempel (Governor) for FPE 2014-03-31. Name and position only; no other personal details recorded.","source_layer":"records","retrieved_date":"2026-10-28","added_by":"records agent"}],"summaries":{"records":"Governor, University of Ontario Institute of Technology (CRA T3010 directors list)"},"added_by":["records agent"],"_intro":{"intro":"Governor, University of Ontario Institute of Technology (CRA T3010 directors list) On the map: 1 link(s) (1 verified)."},"_next":[{"label":"Marj Rempel is a board member of University of Ontario Institute of Technology (verified, 2012-09-01)","entity_id":"ent_organization_ontario_tech_university"},{"label":"See all its dated claims on the timeline","view":"timeline"},{"label":"See timing-pattern leads in public data","view":"leads"}]}},"l":{"lnk_1b27acde15f89bf9":{"description":"Michael Barrett (House of Commons) is named in 4 monthly lobbying communication report(s) filed for this client (2021-11-09 to 2025-10-21).","status_note":"OCL communication reports 517901, 543423, 586696 and 1 more (2021-11-09 to 2025-10-21; 4 in all) filed for The Centre for Israel and Jewish Affairs list 'Michael Barrett', Member of Parliament (House of Commons). Checked in the OCL export of 2026-10-26 (live page 403).","sources":[{"url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=517901","title":"Registry of Lobbyists - communication report 517901","publisher":"Office of the Commissioner of Lobbying of Canada","kind":"public_record","registry":"Federal Registry of Lobbyists - monthly communication reports","record_id":"517901","source_layer":"bloodmoney","batch":"addon-naming-01"},{"url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=543423","title":"Registry of Lobbyists - communication report 543423","publisher":"Office of the Commissioner of Lobbying of Canada","kind":"public_record","registry":"Federal Registry of Lobbyists - monthly communication reports","record_id":"543423","source_layer":"bloodmoney","batch":"addon-naming-01"},{"url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=586696","title":"Registry of Lobbyists - communication report 586696","publisher":"Office of the Commissioner of Lobbying of Canada","kind":"public_record","registry":"Federal Registry of Lobbyists - monthly communication reports","record_id":"586696","source_layer":"bloodmoney","batch":"addon-naming-01"},{"url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=657104","title":"Registry of Lobbyists - communication report 657104","publisher":"Office of the Commissioner of Lobbying of Canada","kind":"public_record","registry":"Federal Registry of Lobbyists - monthly communication reports","record_id":"657104","source_layer":"bloodmoney","batch":"addon-naming-01"},{"url":"https://whofundedgenocide.com/global/","title":"whofundedgenocide.com - Global, Canada tab: federal lobbying communications","publisher":"whofundedgenocide.com","kind":"other","note":"Site's federal lobbying communications dataset (from the OCL communications export). Retrieved 2026-10-28.","source_layer":"bloodmoney","batch":"addon-naming-01"},{"url":"https://open.canada.ca/data/en/dataset/a34eb330-7136-4f5e-9f5f-3ba41df58b06","title":"OCL open data - Monthly Communication Reports (extract dated 2026-10-26)","publisher":"Office of the Commissioner of Lobbying of Canada","date":"2026-10-29","kind":"public_record","registry":"Federal Registry of Lobbyists - monthly communication reports","record_id":"communications_ocl_cal.zip","note":"Bulk export (Communication_PrimaryExport, Communication_DpohExport, SubjectMatters, SubjectMatterDetails) used as the record because the live report pages return HTTP 403.","source_layer":"bloodmoney"}],"lobbying":{"subjects":["International Relations","Justice and Law Enforcement","Taxation and Finance","National Security/Security"],"targets":[{"name":"WAR CRIMES PROSECUTIONS (continuing advocacy to push the denaturalization and deportation of persons found in Canada who lied about their records in the Second World War or more recent conflicts and the prosecution of war criminals when sufficient evidence is adduced.)"},{"name":"Update the Criminal Code of Canada with respect to combating antisemitism and online hate. Create a national strategy to tackle online hate and radicalization using the 2019 Justice Committee report, \"Taking Action to End Online Hate\", as a foundation. A strategy should draw upon the Christchurch Call, and use the International Holocaust Remembrance Alliance definition of antisemitism."},{"name":"Transportation: Assisting in the development of briefings on airport security by Israeli officials for Transport Canada - including ministerial staff."},{"name":"The project ‘United Against Online Hate’ aims to develop a national coalition with numerous targeted communities to actively combat online hate, following recommendations from the study conducted by the House of Commons Standing Committee on Justice and Human Rights. We have been granted $141,000 for the government’s current fiscal year (ending March 31 2021).\r\nWe were also awarded $31,800 for the year April 1 2021 to March 31 2022."},{"name":"Tax credit for volunteerism: proposing that a process be added to provide tax credits for individuals who contribute time to charitable activities on a sustained basis."},{"name":"Taxation and Finance: Discussions regarding CRA tax policies with respect to charitable organizations, and general policies."},{"name":"Raoul Wallenberg \"Park of the Righteous\": For the Government to establish a national park in honour of Raoul Wallenberg paying tribute to individual Canadians who have made a significant contribution to humanitarian causes."},{"name":"Qualifications for refugee status claimants and citizenship and immigration requirements for new immigrants related to standards for qualification for entry"},{"name":"Public Security threats to the safety and security of the Jewish community of Canada and the extension of funding of capital costs and staff training for security of communities at risk"},{"name":"PSC (Public Safety Canada) and Infrastructure Canada seeking program applicability to full range of Jewish communal institutions with respect to the timing of the program and the scope and determination of reimbursements"},{"name":"Provide economic support for the charitable and not-for-profit sector through a direct granting program. Donations from Canadians should be incentivized through a temporary enhancement of the charitable giving tax credit, or through a donor matching program, whereby the government matches donations from Canadians."},{"name":"National Holocaust Memorial: To ensure that the Government of Canada provide resources for year-round access to the memorial as well as educations supports for visitors to the Holocaust Memorial"},{"name":"Myanmar/Burma/Uighurs: Rohinga refugees and displaced persons: For Canada to augment humanitarian allocations to assist the Rohinga refugees in Burma and Bangladesh and implement elements of the recommendations submitted by The Hon. Bob Rae regarding the Rohinga refugee population."},{"name":"Make the Disability Tax Credit refundable, and increase its accessibility by making it inclusive, especially for those with non-physical and/or episodic disabilities. Reforms should be undertaken in partnership with disability advocates, to ensure the application process is simpler, less subjective, and more accessible for individuals and medical professionals alike."},{"name":"Make the Canada Caregiver Credit a refundable tax credit."},{"name":"Launch a parliamentary inquiry on Canadians and global terrorism: Parliament should launch a study on Canadian victims and perpetrators of foreign terrorism to identify gaps and propose solutions in two areas: federal support for victims, and evidence collection on perpetrators."},{"name":"INTERNATIONAL TASK FORCE ON HOLOCAUST EDUCATION, COMMEMORATION AND RESEARCH; ensure that the Government of Canada fulfills its obligations as a full member."},{"name":"International Relations: Discussions on Canadian interventions at the UN regarding economic sanctions approved by the Security Council; Canadian positions on the NPT (Non-proliferation treaty) review conference; Canadian involvement in the Israel-Palestinians peace process."},{"name":"International Development: Advice on Foreign Affairs, Trade and Development of Canada (Global Affairs Canada) approach to aid directed at UNRWA (United Nations Relief and Works Agency); Advice on the renewal of the McGill Middle East Program in Civil Society and Peace Building It exists - since renamed International Community Action Network (ICAN)."},{"name":"Infrastructure and community relations with regard to the expansion of current PSC (Public Safety Canada) security related funding proposals to include broader definitions of participation and extended funding qualification timetables as well as broader range of items to be funded"},{"name":"Include a question on religion in every census, instead of every second census."},{"name":"Immigration: Discussions regarding the Immigration Refugee Board policies regarding refugee claimants from Israel; Discussions regarding overall Canadian immigration policy, integration of new Canadians and Israeli \"best practices\" regarding new immigrant absorption (e.g., certification of foreign trained medical professionals) and language training."},{"name":"Hate speech and internet-based hate: For Canada to adopt policies – either/and through legislation or policies adjustments that will provide measurable standards for internet-based dissemination of hate speech, including explicit provisions within the Crimical Code and/or the Human Rights Act."},{"name":"Government Procurement: Facilitation of Canada-Israel meetings at ministerial level on issues of budget and procurement \"best practices\"."},{"name":"Establish a security rebate program for places of worship, schools and community centres. Institutions that pay for security personnel (such as guards from licensed companies or paid duty police officers) could submit those receipts with their annual filing to Canada Revenue Agency and be reimbursed for a portion of the total cost."},{"name":"Equip police departments to counter hate crimes and support targeted communities by providing additional resources to bolster existing police hate crime and community liaison units. Where such units do not exist, funding should be provided to establish them."},{"name":"End the ban on blood donations from men-who-have-sex-with-men, and implement new policies which ensure Canada's blood supply is safe, without being discriminatory."},{"name":"Diplomatic relations with Iran should not be renewed until specific conditions are met, including an end to calls for the destruction of Israel, an end to state-sponsored terrorism, and the provision of all evidence related to Ukraine International Airlines Flight 752. The entirety of the Islamic Revolutionary Guard Corps should be banned by the government."},{"name":"Digital Citizen Contribution Program (DCCP): The objective of the project is to combat online disinformation and hate, specifically, antisemitism and antisemitic conspiracy theories related to COVID-19 where it is spreading: online via social media. Antisemitism cannot be allowed to permeate civil discourse and become mainstream. Activities include: \r\n•Collect examples of how antisemitism presents itself in the context of COVID19\r\n•Create website landing page lor campaign to highlight the campaign's purpose and goals\r\n•Prepare social media calendar for the duration of the campaign\r\n•Prepare Facebook ads, prepare toolkit to distribute to partner organizations to promote the campaign\r\n•Program content for campaign, run Facebook ads, and ensure participation from various cultural groups; and\r\n•Report to government and stakeholders on the outcome of the campaign.\r\n\r\nThe Digital Citizen Contribution Program (DCCP) supports the priorities of the Digital Citizen Initiative by providing time-limited financial assistance that will support democracy and social cohesion in Canada in a digital world by enhancing and/or supporting efforts to counter online disinformation and other online harms and threats to our country's democracy and social cohesion."},{"name":"Department of Citizenship and Immigration Act, related to the application of and the issuance of visas."},{"name":"Defense: Canadian participation in Operation Proteus; Discussions on Canada-Israel military cooperation, joint training exercises and military staff exchanges."},{"name":"Dairy Board: tariff exemptions for kosher cheese products: To ensure that kosher cheese products not produced domestically be designated as tariff-exempt dairy products."},{"name":"Crown-Indigenous Relations and Northern Affairs Canada: Assisting Aboriginal leaders and Aboriginal women's groups in learning new models of community development through presentations on Israeli development models at MASHAV (Israel's Agency for International Development Cooperation in the Ministry of Foreign Affairs. Israel's equivalent of CIDA). Canadian participation in the United Nations Declaration on the Rights of Indigenous Peoples."},{"name":"Continuing support of the Government of Canada's policy in maintaining the office of the special advisor on antisemitism of the Organization for Security and Cooperation in Europe (OSCE)."},{"name":"Conflict of Interests, Ethics, Lobbying, Canada Revenue Agency. Ensuring CIJA fully respects all its legal and regulatory obligations while advocating for the current framework to be more efficient and respectful of the needs, objectives and resources of cultural and religious communities."},{"name":"Civil remedy included in the Canadian Human Rights Act with respect to combating antisemitism."},{"name":"CITIZENSHIP ACT (continued support for the power of the state under the current citizenship act to remove citizenship in cases involving war crimes, crimes against humanity, terrorism and extreme promotion of hate.)"},{"name":"Canadian participation in International Holocaust Remembrance Alliance (IHRA)"},{"name":"Canadian diplomatic relations related to the trade agreements with Israel and other nations in the Middle East"},{"name":"Canada-Israel bilateral relations related to trade, investment and scientific and academic exchanges"},{"name":"Canada and Israel relationship with regard to expanding trade between Canada and Israel through the promotion, application and expansion of free trade agreement"},{"name":"Broadcasting: Discussions regarding the award of new broadcast licenses by the CRTC"},{"name":"Assisted living and low-income housing for vulnerable populations. Ensure those with developmental disabilities benefit from the government programs for affordable housing, and that a specific portion of the funds allocated for housing be designated for those with developmental disabilities. The national housing strategy should be implemented, with a portion of the funding earmarked for vulnerable populations, such as those with disabilities, seniors, and those who have escaped domestic violence."},{"name":"Anti racism initiatives and expand support by Canadian government of different initiatives to promote tolerance and diversity, including genocide awareness, commemoration and education."},{"name":"Agriculture Canada: Assist in securing termination of Israeli ban on Canadian beef imports as a result of BSE (Bovine Spongiform Encephalopathy) protocols."},{"name":"Agriculture: Canadian Food Inspection Agency regulations regarding ritual slaughter (Chapter 12) and labeling."},{"name":"Advocating for the development of a national anti-poverty strategy."},{"name":"Advocate for restitution for Holocaust Survivors: Canada should continue leveling diplomatic pressure on countries in Eastern Europe that have evaded their responsibility to pass meaningful restitution laws."},{"name":"A civil remedy based in human rights law, included in the Canadian Human Rights Act, with respect to combating hate speech, including antisemitism. Training for provincial attorneys general, prosecutors, and police to enforce Criminal Code hate speech provisions. Training and parameters should cite the International Holocaust Remembrance Alliance working definition of antisemitism."},{"name":"Accountability for Anti-Racism Initiatives: Public accountability measures should be developed and implemented to support and uphold genuine progress in combating hate in all its forms, as outlined in Building a Foundation for Change: Canada’s Anti-Racism Strategy 2019–2022."},{"name":"Animal Welfare - Aligning shechita process (kosher slaughter) and compliance with updated CFIA regulations regarding animal welfare"},{"name":"Introduce 'bubble legislation,' or zones of exemption for protests around religious institutions."},{"name":"Call a meeting of federal, provincial and territorial ministers to address the steep rise in antisemitism in Canada."},{"name":"Canada's adoption of the IHRA definition of antisemitism. Ensuring all government policy abides by this document."}],"communications":[{"date":"2021-11-09","official":"Michael Barrett","institution":"House of Commons","officials":[{"name":"Michael Barrett","title":"Member of Parliament"}],"report_url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=517901","subjects":["International Relations"]},{"date":"2022-09-20","official":"Michael Barrett","institution":"House of Commons","officials":[{"name":"Michael Barrett","title":"Member of Parliament"}],"report_url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=543423","subjects":["International Relations"]},{"date":"2023-11-30","official":"Michael Barrett","institution":"House of Commons","officials":[{"name":"Michael Barrett","title":"Member of Parliament"}],"report_url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=586696","subjects":["International Relations"]},{"date":"2025-10-21","official":"Michael Barrett","institution":"House of Commons","officials":[{"name":"Michael Barrett","title":"Member of Parliament"}],"report_url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/cmmLgPblcVw?comlogId=657104","subjects":["Justice and Law Enforcement","Taxation and Finance","National Security/Security"]}],"registry_url":"https://lobbycanada.gc.ca/app/secure/ocl/lrs/do/vwRg?cno=111&regId=974223"},"_x":{"text":"According to bl00d.money: Michael Barrett (House of Commons) is named in 4 monthly lobbying communication report(s) filed for this client (2021-11-09 to 2025-10-21). Lobbying details from the federal Registry of Lobbyists, checked 2026-10-29. What was lobbied for: subject headings International Relations, Justice and Law Enforcement, Taxation and Finance, National Security/Security; the registry describes it as 'Update the Criminal Code of Canada with respect to combating antisemitism and online hate. Create a…'; 'Transportation: Assisting in the development of briefings on airport security by Israeli officials…' and 52 more. Whom it targeted: House of Commons (4 reports); officials named most often: Michael Barrett (Member of Parliament, House of Commons). Communications: 4 communication report(s), first 2021-11-09, last 2025-10-21. Status: verified, an official public r